local ADDON_NAME, ns = ...

---------------------------------------------------------------------------
-- Lazy new-profile seed.
--
-- The shipped defaults live ONLY in the compressed Starter Profile export
-- string (importstrings/starter_profile.lua, root TOC) — the former 347 KB
-- literal table paid its parse+alloc on EVERY login; the decode below runs
-- once, at first profile creation / floor reseed, and most logins never
-- pay it at all.
--
-- The string is generated by tools/gen_new_profile_seed.lua and is ALREADY
-- stripped (every "_"-prefixed meta/latch key at any depth + fpsBackup;
-- orphan CDM container satellites purged) — no runtime scrubbing here. A
-- seeded profile still reads as unmigrated (stored schema 0) and the
-- migration layer stamps _schemaVersion/_defaultsVersion afterwards.
--
-- Payload shape (tools/gen_new_profile_seed.lua): seed keys at top level
-- plus a _h3z0uiBundledGlobals block, dropped on decode.
--
-- Applied to EVERY newly-created profile (and a fresh install's Default)
-- via the AceDB OnNewProfile hook in core/init.lua. Existing profiles are
-- never touched; copies keep their source. defaults.lua stays the legacy
-- fallback so the shadow-defaults pin (core/compatibility.lua) sees no
-- diff for existing users.
---------------------------------------------------------------------------

local decodedSeed

local function LoadStarterEntry()
    if H3z0UI and H3z0UI.imports then
        local entry = H3z0UI.imports.StarterProfile
        if entry ~= nil then return entry end
    end
    local loaders = H3z0UI and H3z0UI._importLoaders
    local loader = loaders and loaders.StarterProfile
    if type(loader) == "function" then
        return loader()
    end
    return nil
end

local function DecodeSeed()
    local AceSerializer = LibStub and LibStub("AceSerializer-3.0", true)
    local LibDeflate = LibStub and LibStub("LibDeflate", true)
    if not (AceSerializer and LibDeflate) then
        return nil, "AceSerializer-3.0/LibDeflate unavailable"
    end

    local entry = LoadStarterEntry()
    local str = type(entry) == "table" and entry.data or entry
    if type(str) ~= "string" then
        return nil, "Starter Profile import string missing"
    end

    str = str:gsub("%s+", "")
    local prefix = str:match("^([A-Za-z][A-Za-z0-9]*%d):")
    if prefix then
        str = str:sub(#prefix + 2)
    end

    local compressed = LibDeflate:DecodeForPrint(str)
    if not compressed then
        return nil, "starter seed string corrupt (decode)"
    end
    local serialized = LibDeflate:DecompressDeflate(compressed)
    if not serialized then
        return nil, "starter seed string corrupt (decompress)"
    end
    local ok, payload = AceSerializer:Deserialize(serialized)
    if not ok or type(payload) ~= "table" then
        return nil, "starter seed string corrupt (deserialize)"
    end

    payload._h3z0uiBundledGlobals = nil

    -- H3z0 UI modules (unit / party / raid frames, chat, nameplates) keep their own defaults
    for _, key in ipairs({ "h3z0uiUnitFrames", "unitFrames", "h3z0uiGroupFrames", "partyFrames", "raidFrames",
        "chat", "nameplates", "castBar", "targetCastBar", "focusCastBar", "addonAccentColor",
        "actionBars", "ncdm", "powerBar", "secondaryPowerBar", "powerColors", "viewers", "customTrackers",
        "cdmVisibility", "unitframesVisibility", "customTrackersVisibility", "minimap", "datatext", "hoverName" }) do
        payload[key] = nil
    end
    if type(payload.skyriding) == "table" then payload.skyriding.enabled = false end
    if type(payload.infobar) == "table" then payload.infobar = nil end
    if type(payload.bags) == "table" then
        payload.bags.enabled = nil
        if type(payload.bags.appearance) == "table" then
            payload.bags.appearance.layoutMode = nil
            payload.bags.appearance.qualityColorText = nil
        end
    end
    if type(payload.frameAnchoring) == "table" then
        for _, key in ipairs({ "playerFrame", "targetFrame", "totFrame", "petFrame", "focusFrame",
            "playerCastbar", "targetCastbar", "focusCastbar", "petCastbar", "totCastbar",
            "partyFrames", "raidFrames", "bossFrames",
            "cdmEssential", "cdmUtility", "buffIcon", "buffBar",
            "minimap", "datatextPanel",
            "bar1", "bar2", "bar3", "bar4", "bar5", "bar6", "bar7", "bar8", "petBar", "stanceBar" }) do
            payload.frameAnchoring[key] = nil
        end
    end
    return payload
end

---------------------------------------------------------------------------
-- H3z0 UI default profile (importstrings/h3z0_default_profile.lua): the full
-- H3z0 UI setup. When it is there and made for this client, new profiles,
-- Reset Profile and the wizard's fresh start get exactly this profile; only
-- the string's own wrapper keys are left out. Its Blizzard Edit Mode layout
-- is kept apart (ns.GetH3z0DefaultEditMode) and applied by the callers.
---------------------------------------------------------------------------
local defaultFull, defaultEditMode
local defaultPositions

local function DecodeH3z0Default()
    if defaultFull ~= nil then return defaultFull or nil end
    defaultFull = false
    local loaders = H3z0UI and H3z0UI._importLoaders
    local loader = loaders and loaders.H3z0Default
    if type(loader) ~= "function" then return nil end
    local AceSerializer = LibStub and LibStub("AceSerializer-3.0", true)
    local LibDeflate = LibStub and LibStub("LibDeflate", true)
    if not (AceSerializer and LibDeflate) then return nil end
    local ok, payload = pcall(function()
        local entry = loader()
        local str = type(entry) == "table" and entry.data or entry
        str = tostring(str or ""):gsub("%s+", "")
        local prefix = str:match("^([A-Za-z][A-Za-z0-9]*%d):")
        if prefix then str = str:sub(#prefix + 2) end
        local okD, data = AceSerializer:Deserialize(LibDeflate:DecompressDeflate(LibDeflate:DecodeForPrint(str)))
        if not okD or type(data) ~= "table" then return nil end
        return data
    end)
    if not ok or type(payload) ~= "table" then return nil end
    -- the frame positions of the H3z0 UI setup are the same on Midnight and Forever (Layout Sets reads them)
    defaultPositions = payload
    if ns.Client and payload._h3z0uiClient and payload._h3z0uiClient ~= ns.Client.flavor then return nil end
    defaultEditMode = payload._h3z0uiEditMode
    for _, k in ipairs({ "_h3z0uiClient", "_h3z0uiEditMode", "_h3z0uiBundledGlobals", "_migrationBackup", "_needsStarterReseed", "setup" }) do
        payload[k] = nil
    end
    -- the H3z0 Pro M+ timer is the H3z0 UI default layout
    if type(payload.mplusTimer) == "table" then payload.mplusTimer.layoutMode = "pro" end
    -- Blizzard Frame Mover starts off (Blizzard's windows can't be dragged until it is turned on)
    if type(payload.blizzardMover) == "table" then payload.blizzardMover.enabled = false end
    defaultFull = payload
    return payload
end

-- the H3z0 UI default setup for its frame positions only: also on a client the full setup is not made for
function ns.GetH3z0DefaultPositions()
    DecodeH3z0Default()
    if defaultPositions == nil then return nil end
    local c = defaultPositions._h3z0uiClient
    if c and ns.Client and c ~= ns.Client.flavor
        and not ((c == "retail" or c == "forever") and (ns.Client.flavor == "retail" or ns.Client.flavor == "forever")) then
        return nil
    end
    return defaultPositions
end

function ns.GetH3z0DefaultEditMode()
    DecodeH3z0Default()
    return defaultEditMode
end

function ns.HasH3z0DefaultProfile()
    return DecodeH3z0Default() ~= nil
end

function ns.GetNewProfileSeed()
    local full = DecodeH3z0Default()
    if full then return full end
    if decodedSeed == nil then
        local seed, err = DecodeSeed()
        if not seed then
            local report = ("H3z0UI: Starter Profile seed decode failed (%s); new profiles keep legacy defaults"):format(err or "?")
            if geterrorhandler then
                geterrorhandler()(report)
            else
                print(report)
            end
            decodedSeed = false
        else
            decodedSeed = seed
        end
    end
    return decodedSeed or nil
end

local function DeepApply(dst, src)
    for k, v in pairs(src) do
        if type(v) == "table" then
            local d = dst[k]
            if type(d) ~= "table" then d = {}; dst[k] = d end
            DeepApply(d, v)
        else
            dst[k] = v
        end
    end
end

function ns.ApplyNewProfileSeed(profile)
    if type(profile) ~= "table" then return end
    local seed = ns.GetNewProfileSeed()
    if not seed then return end
    DeepApply(profile, seed)
end
